export const fameId = (number: StoryLessonNumber) => `conversational-skills-L7-C4-${number}-${fameEpisodes[number].skill}-en-v1`;

export function buildFameLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, fameEpisodes[number], previous, reference, {
    id: fameId(number), chapterName: 'The Price of Fame', pronunciation: famePronunciation[number],
    setting: 'The fictional Spotlight Works and Apex Entertainment music partnership in Japan, with recording and branding meetings, a convenience store, promotional touring including an Osaka rehearsal, and a team dinner.',
    previousSummary: index === 0 ? contractEpisodes[9].closing : fameEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(7)}\nReference: Beyond the Spotlight, Chapter 4: The Price of Fame. Owner target TOEIC 550-780 overrides reference C1-C2. Eight source episodes map to slots 1-4 and 6-9, with 5/10 dynamic checkpoints. English only, four expressions, only Step B pronunciation with exact bold stress; no Part III or extra pronunciation commentary. Objective first, plain Apply situations, separate questions, direct roles and short tutor-first dialogues. Private listening, fresh reading notes, fixed English feedback. No new artwork, romance, model API calls or credits. Continue core cast and Apex representative Mr. Shibata. Introduce named senior producer Ms. Hoshino without identifying her as Chapter 3’s unnamed producer. Three weeks after signing: tomorrow has three interviews, rehearsal and late-night recording. Audience growth exceeds expectations without exact metrics. Workload concern is raised, not resolved. Kai politely declines store photo because exhausted; later post judges him arrogant, with no identified poster or motive. Team supports privacy boundaries; Jisoo prepares a short thanks message, no confirmed publication or full campaign. Quiet Streets is a new slow reflective song about pre-success experience; Ms. Hoshino praises writing but proposes postponement for current energetic branding. Maya supports discussion through negotiated creative approval, not unilateral release or total veto. Branding outfits/scripted interviews remain a proposal; representative does not confirm a ban on all other feelings. Mid-tour Osaka fatigue and concentration difficulty lead to break and evening request for adjustments, not medical diagnosis or an agreed revision yet. Following morning Jisoo apologises for scheduling posts without confirming Luis’s unfinished videos; Luis acknowledges raising concerns late. No sabotage, broken-up team or proven lost exposure. Later that week Apex reviews commitments/alternatives and agrees to revised schedule with fewer interviews, protected rest and realistic production timelines. Promotion continues; no precise dates, rest-day counts or guaranteed growth. Weeks later Kai records a new version of Quiet Streets and team celebrates completed revised tour. Jisoo’s encouraging latest-release news names no song; do not identify it as Quiet Streets or claim new recording officially released. Fictional Tokyo Sound Festival matters on Apex calendar, with no real-world ranking claim. Apex wants Kai for special set and agrees only to consider Quiet Streets. No confirmed inclusion, settled set list, completed festival performance or future-chapter resolution. End with interest, preparation and pride beyond audience size.`,
  });
  lesson.storyData.storyTitle = 'Beyond the Spotlight';
  lesson.storyData.characters = [
    { id: 'maya', name: 'Maya Kurose', role: 'main', description: 'Creative producer at Spotlight Works. She supports Kai’s range, helps resolve workload and coordination concerns, and negotiates a revised schedule.' },
    { id: 'natsumi', name: 'Natsumi Ito', role: 'supporting', description: 'Talent manager who supports personal boundaries, calls for a rehearsal break, negotiates adjustments and shares the festival opportunity.' },
    { id: 'jisoo', name: 'Jisoo', role: 'supporting', description: 'Digital strategist who reports audience growth, prepares a respectful fan message and apologises for scheduling posts without consulting Luis.' },
    { id: 'luis', name: 'Luis', role: 'supporting', description: 'Videographer concerned about authentic presentation and realistic deadlines. He acknowledges raising workload concerns late.' },
    { id: 'kai', name: 'Kai Nakamura', role: 'supporting', description: 'Singer-songwriter whose growing career strains his energy and personal time. He develops Quiet Streets and broadens his definition of success.' },
    { id: 'shibata', name: 'Mr. Shibata', role: 'supporting', description: 'Apex representative who discusses promotion, agrees to schedule revision after review and later shares the festival opportunity.' },
    { id: 'hoshino', name: 'Ms. Hoshino', role: 'supporting', description: 'Apex senior producer who praises Quiet Streets but suggests postponing it because of the current campaign strategy.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 7, chapter: 4, lessonNumber: number,
    levelBadge: 'INTERMEDIATE', chapterLabel: 'Chapter 4: The Price of Fame', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 550-780', authoringLanguageRevision: 'toeic-v1' };
}

export function buildFameChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildFameLesson(number, {}, reference));
}
